export function Blockquote({
  quote = "{{quote}}",
  citation = "{{citation}}",
  style = "{{style}}",
  accent = "{{accent}}",
  radius = {{radius}},
}) {
  const wrap = {
    classic: { borderLeft: `4px solid ${accent}` },
    boxed: { border: `1.5px solid ${accent}`, boxShadow: "0 8px 24px rgba(36,20,48,.12)" },
    minimal: { paddingLeft: 0 },
  }[style] ?? {};
  return (
    <blockquote style={{ font: "17px/1.6 Georgia, 'Times New Roman', serif", color: "#241430", background: "#FAF7F2",
      maxWidth: 420, padding: "20px 24px", margin: 0, borderRadius: radius, ...wrap }}>
      {style !== "minimal" && (
        <svg style={{ color: accent, display: "block", marginBottom: 8 }} viewBox="0 0 32 24" width="28" height="21" aria-hidden="true">
          <path d="M0 24V14.5C0 6.5 5 1 13 0l1.5 4C9 5.5 6 9 6 14h7v10H0zm18 0V14.5C18 6.5 23 1 31 0l1.5 4C27 5.5 24 9 24 14h7v10H18z" fill="currentColor" />
        </svg>
      )}
      <p style={{ margin: "0 0 10px" }}>{quote}</p>
      <footer style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#24143099" }}>&#8212; {citation}</footer>
    </blockquote>
  );
}
